d['brs']=[r for r in d['brs'] if r[0] not in ['BR03','BR05']]+[['BR11','원천 결과를 반복 입력하지 않는다','공통','SIR-001','원천 일치·갱신시각·조회 실패','W08']]
for b in d['brs']:
    if b[0]=='BR01':b[1]='예약 가능한 선택지를 한 화면에서 찾고 원 채널로 이동한다';b[4]='날짜 비교 왕복·필터 보존·오인된 예약완료'
    if b[0]=='BR07':b[1]='권한에 맞게 내부 검토하고 조회한다';b[4]='무권한 열람·잘못된 검토 상태'
    if b[0]=='BR02':b[5]='W04,W09'
    if b[0]=='BR04':b[5]='W05,W09'

roundwon=lambda x:math.floor(x+.5)
budget={}
for p in ['1단계','2단계','운영']:
    if p=='운영':
        totalmm=sum(o[3] for o in d['ops']);rr={r[0]:r[2] for r in roles};labor=roundwon(sum(o[3]*rr[o[2]] for o in d['ops']));direct=sum(x[2]*x[3] for x in d['opsdirect'])
    else:
        subset=[w for w in d['wps'] if w[1]==p];totalmm=sum(sum(w[4]) for w in subset);labor=roundwon(sum(sum(mm*roles[i][2] for i,mm in enumerate(w[4])) for w in subset));direct=sum(x[4]*x[5] for x in d['direct'] if x[1]==p)
    overhead=roundwon(labor*d['overhead']);fee=roundwon((labor+overhead)*d['fee']);net=labor+overhead+fee+direct;vat=roundwon(net*d['vat']);gross=net+vat
    budget[p]=dict(mm=round(totalmm,2),labor=labor,overhead=overhead,fee=fee,direct=direct,net=net,vat=vat,gross=gross)
    if p!='운영':budget[p].update(cap=d['caps'][p],headroom=d['caps'][p]-gross)
d['budget']=budget
d['revision']='목표 상한을 반영해 실제 납품 범위를 축소한 시안. v0.1의 동일 범위 가격 인하가 아님.'
